/**
 * SVGスプライトページ先頭挿入用関数
 * @returns {HTMLElement}
 */
function ensureSpriteRoot() {
	let spriteRoot = document.querySelector('#svg-sprite');
	if (!spriteRoot) {
		spriteRoot = document.createElement('div');
		spriteRoot.id = 'svg-sprite';
		spriteRoot.setAttribute('aria-hidden', 'true');
		document.body.prepend(spriteRoot);
	}
	return spriteRoot;
}

/**
 * パンくずリスト自動生成関数
 * @returns {string} パンくずリストのHTML文字列
 */
function createBreadcrumbContent() {
	const path = window.location.pathname;
	const pathSegments = path.split('/').filter((segment) => segment.length > 0);

	let currentPath = '/';
	let breadcrumbHTML = '<ul class="breadcrumb__ul">';

	breadcrumbHTML +=
		'<li class="breadcrumb__li"><a href="/">Home</a></li>&nbsp;&gt;&nbsp;';

	pathSegments.forEach((segment, index) => {
		currentPath += segment + '/';
		const isLast = index === pathSegments.length - 1;
		const linkText = document.title.replace(' - CiderTechLab', '');

		if (!isLast) {
			breadcrumbHTML += `<li class="breadcrumb__li"><a href="${currentPath}">${linkText}</a></li>&nbsp;&gt;&nbsp;`;
		} else {
			breadcrumbHTML +=
				`<li class="breadcrumb__li">` +
				document.title.replace(' - CiderTechLab', '') +
				`</li>`;
		}
	});

	breadcrumbHTML += '</ul>';
	console.log('breadcrumbHTML:', breadcrumbHTML);
	return breadcrumbHTML;
}

/**
 * ページロード後に実行
 */
document.addEventListener('DOMContentLoaded', () => {
	const spritePlaceholder = ensureSpriteRoot();
	if (!document.querySelector('#icon-github')) {
		spritePlaceholder.innerHTML = icons;
	}

	const headerPlaceholder = document.querySelector('header');
	if (headerPlaceholder) {
		headerPlaceholder.innerHTML = headerContent;
	}

	const breadcrumbPlaceholder = document.querySelector('.breadcrumb');
	if (breadcrumbPlaceholder) {
		breadcrumbPlaceholder.innerHTML = createBreadcrumbContent();
	}

	const footerPlaceholder = document.querySelector('footer');
	if (footerPlaceholder) {
		footerPlaceholder.innerHTML = footerContent;
	}

	// ページトップへスムーズスクロール
	const pagetopLink = document.querySelector('.pagetopscroll-icon__link');
	if (pagetopLink) {
		pagetopLink.addEventListener('click', (e) => {
			e.preventDefault();
			window.scrollTo({ top: 0, behavior: 'smooth' });
		});
	}

	// オーバーレイをbody直下に作成・挿入（position: fixedが正常に機能するように）
	const overlay = document.createElement('div');
	overlay.className = 'header-nav--overlay';
	document.body.appendChild(overlay);

	// ハンバーガーボタンのクリックハンドラー
	const hamburger = document.querySelector('.header-nav-hamburger');
	const nav = document.querySelector('nav');
	if (hamburger) {
		hamburger.addEventListener('click', () => {
			const isOpen = hamburger.classList.toggle('is-open');
			overlay.classList.toggle('is-open');
			if (nav) {
				nav.classList.toggle('is-open');
			}
			hamburger.setAttribute('aria-expanded', String(isOpen));
			hamburger.setAttribute(
				'aria-label',
				isOpen ? '目次を閉じる' : '目次を開く'
			);
		});
	}
});
